#!/usr/bin/env node
/**
 * Bundles the full resume PDFs (built by `npm run resume:full`) into a module
 * the resume-links Worker imports. The generated file is git-ignored: the PDFs
 * carry a phone number and must not land in the repository.
 *
 * Usage: node resume/bundle-worker.mjs [--in dist/resume-full]
 */
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, '..');
const OUTPUT = join(ROOT, 'worker/src/pdfs.generated.js');

const VARIANTS = {
  generic: 'jonathan-yen-resume.pdf',
  frontend: 'jonathan-yen-resume-frontend.pdf',
  fullstack: 'jonathan-yen-resume-fullstack.pdf',
};

const inputIndex = process.argv.indexOf('--in');
const inputDir = resolve(ROOT, inputIndex === -1 ? 'dist/resume-full' : process.argv[inputIndex + 1]);

const entries = [];
let total = 0;

for (const [variant, filename] of Object.entries(VARIANTS)) {
  const bytes = await readFile(join(inputDir, filename));
  total += bytes.length;
  entries.push(`  ${variant}: '${bytes.toString('base64')}',`);
}

await writeFile(
  OUTPUT,
  `// Generated by resume/bundle-worker.mjs — do not edit, do not commit.
const encoded = {
${entries.join('\n')}
};

const decode = (base64) =>
  Uint8Array.from(atob(base64), (character) => character.charCodeAt(0));

export default Object.fromEntries(
  Object.entries(encoded).map(([variant, base64]) => [variant, decode(base64)]),
);
`,
);

console.log(`bundled ${Object.keys(VARIANTS).length} PDFs (${(total / 1024).toFixed(0)} KB raw) into ${OUTPUT.replace(`${ROOT}/`, '')}`);
